<?php

declare(strict_types=1);

namespace Keel\Container\Compiled;

use Keel\Container\ContainerInterface;
use Keel\Container\Definition;
use Keel\Container\Exception\CircularDependencyException;
use Keel\Container\Exception\ContainerException;
use Keel\Container\Exception\NotFoundException;
use Keel\Container\Reflection\ClassAttributes;
use Keel\Container\Reflection\Instantiator;
use Keel\Container\Resetter;
use Psr\Container\ContainerInterface as PsrContainerInterface;

/**
 * Base class of the container generated by Compiler. The generated subclass overrides the
 * constants and implements create() with one private method per service.
 *
 * Lookup order, shared with the runtime Container: pre-built instances, compiled services,
 * parameters, then classes autowired at runtime.
 */
abstract class AbstractCompiledContainer implements ContainerInterface
{
    /** @var array<string, true> ids with a generated factory method */
    protected const array SERVICE_IDS = [];

    /** @var array<string, true> subset of SERVICE_IDS that was autowired, not registered: off with autowire = false */
    protected const array AUTOWIRED = [];

    /** @var array<string, true> ids that are not cached */
    protected const array TRANSIENT = [];

    /** @var array<string, string> alias => final id */
    protected const array ALIASES = [];

    /** @var array<string, list<string>> tag => ids */
    protected const array TAGS = [];

    /** @var array<string, mixed> */
    protected const array PARAMETERS = [];

    /** @var list<string> ids whose objects must be passed to the constructor */
    protected const array INSTANCE_IDS = [];

    /** Compiler::contentHash() of the generated file; App detects a rewritten cache with it. */
    public const string CONTENT_HASH = '';

    /** @var array<string, mixed> */
    private array $instances;

    /** @var array<string, true> */
    private array $resolving = [];

    /** @var array<string, Definition> */
    private array $autowired = [];

    private ?Instantiator $instantiator;

    /**
     * @param array<string, object> $instances pre-built objects for every id in INSTANCE_IDS
     * @param bool                  $autowire  build classes that were not registered: the ones autowired at
     *                                         compile time and, with reflection, the ones unknown then. Off,
     *                                         only registered definitions resolve, as in the runtime Container
     */
    public function __construct(
        array $instances = [],
        private readonly bool $autowire = true,
        ?Instantiator $instantiator = null,
    ) {
        $missing = array_diff(static::INSTANCE_IDS, array_keys($instances));
        if ($missing !== []) {
            throw new ContainerException(
                'Compiled container requires instances for: ' . implode(', ', $missing),
            );
        }

        $this->instances = $instances;
        $this->instances[PsrContainerInterface::class] = $this;
        $this->instances[ContainerInterface::class] = $this;
        // Reflection machinery is loaded only if a class unknown at compile time is requested.
        $this->instantiator = $instantiator;
    }

    public function get(string $id): mixed
    {
        $id = static::ALIASES[$id] ?? $id;

        if (array_key_exists($id, $this->instances)) {
            return $this->instances[$id];
        }

        if ($this->compiled($id)) {
            $this->enter($id);
            try {
                $service = $this->create($id);
            } finally {
                unset($this->resolving[$id]);
            }

            if (!isset(static::TRANSIENT[$id])) {
                $this->instances[$id] = $service;
            }

            return $service;
        }

        if (array_key_exists($id, static::PARAMETERS)) {
            return static::PARAMETERS[$id];
        }

        $definition = $this->autowiredDefinition($id) ?? throw $this->notFound($id);

        $this->enter($id);
        try {
            $service = ($this->instantiator ??= new Instantiator())->create($definition, $this);
        } finally {
            unset($this->resolving[$id]);
        }

        if ($definition->shared) {
            $this->instances[$id] = $service;
        }

        return $service;
    }

    public function has(string $id): bool
    {
        $id = static::ALIASES[$id] ?? $id;

        return array_key_exists($id, $this->instances)
            || $this->compiled($id)
            || array_key_exists($id, static::PARAMETERS)
            || $this->autowiredDefinition($id) !== null;
    }

    public function tagged(string $tag): array
    {
        $services = [];
        foreach (static::TAGS[$tag] ?? [] as $id) {
            $service = $this->get($id);
            if (is_object($service)) {
                $services[] = $service;
            }
        }

        return $services;
    }

    public function reset(): void
    {
        Resetter::reset($this->instances);
    }

    /**
     * Generated: instantiates the service with the given id.
     */
    abstract protected function create(string $id): mixed;

    /**
     * PSR-11 reserves NotFoundExceptionInterface for the id that was asked for; a dependency
     * missing deeper in the chain is a plain ContainerException carrying the chain.
     */
    private function notFound(string $id): ContainerException
    {
        if ($this->resolving === []) {
            return NotFoundException::unresolvable($id, [], $this->autowire);
        }

        return ContainerException::unresolvable($id, array_keys($this->resolving), $this->autowire);
    }

    /**
     * A generated service, unless it was autowired at compile time and autowiring is off.
     */
    private function compiled(string $id): bool
    {
        return isset(static::SERVICE_IDS[$id]) && ($this->autowire || !isset(static::AUTOWIRED[$id]));
    }

    private function enter(string $id): void
    {
        if (isset($this->resolving[$id])) {
            throw CircularDependencyException::forChain([...array_keys($this->resolving), $id]);
        }

        $this->resolving[$id] = true;
    }

    private function autowiredDefinition(string $id): ?Definition
    {
        if (isset($this->autowired[$id])) {
            return $this->autowired[$id];
        }

        if (!$this->autowire || !class_exists($id)) {
            return null;
        }

        $class = new \ReflectionClass($id);
        if (!$class->isInstantiable()) {
            return null;
        }

        $definition = new Definition($id);
        ClassAttributes::apply($class, $definition);

        return $this->autowired[$id] = $definition;
    }
}
